WHERE d.workspace_id = #{q.workspaceId}



    AND EXISTS (SELECT 1 FROM demand_watch dw
                WHERE dw.workspace_id = d.workspace_id AND dw.demand_id = d.id
                  AND dw.user_id = #{q.userId})



    AND d.status = 'review'
     AND (d.created_by IS NULL OR d.created_by <> #{q.userId}) 

      AND (d.created_by IS NULL OR d.created_by <> #{q.displayName})

    AND 



    AND (
      d.created_by = #{q.userId}

        OR d.created_by = #{q.displayName}

    )



          AND d.created_by = #{q.displayName}
           AND (d.created_by IS NULL OR d.created_by <> #{q.userId}) 

        AND 1 = 0




 AND d.status = #{q.status} 

  AND (d.title LIKE CONCAT('%', #{q.q}, '%')
       OR d.description LIKE CONCAT('%', #{q.q}, '%')
       OR d.demand_no = #{q.itemNo}
       OR d.source LIKE CONCAT('%', #{q.q}, '%'))


  AND d.priority IN
  #{p}


  AND d.req_id IN
  #{r}


  AND NOT EXISTS (SELECT 1 FROM project_member pm
                  WHERE pm.workspace_id = d.workspace_id
                    AND pm.project_id = d.req_id
                    AND pm.user_id = #{q.viewerId}
                    AND pm.access = 'none')


AND EXISTS (SELECT 1 FROM workspace_member wmv
            WHERE wmv.workspace_id = d.workspace_id AND wmv.user_id = #{q.userId})

mapper.select:
SELECT  FROM demand d
LEFT JOIN project_version v ON v.workspace_id = d.workspace_id AND v.id = d.version_id


LIMIT #{q.limit} OFFSET #{q.offset}
